        elif len(current) == 2:
            if current[0] < 10 and current[0] + current[1] < 10:
                self._complete_frame()
                self.game_over = True
            # spare or strike: need 1 more bonus roll
        elif len(current) == 3:
            self._complete_frame()
            self.game_over = True

